SELECT ab.availsum + ab.frozensum AS wallet_excl_margin
FROM accountbalances ab
WHERE trim(ab.usertag) = 'U810391';

SELECT SUM(f.feetotal) AS total_fees_on_cancelled_orders
FROM fees f
JOIN orders o ON f.orderslink = o.recordvault
WHERE o.recordvault IN (
  SELECT oe.ordersmark FROM orderexecutions oe WHERE oe.cancelnote IS NOT NULL
);

WITH cancelled_orders AS (
  SELECT DISTINCT ordersmark FROM orderexecutions WHERE cancelnote IS NOT NULL
)
SELECT SUM(f.feetotal) AS total_fees
FROM fees f
WHERE f.orderslink IN (SELECT ordersmark FROM cancelled_orders);
